class Solution:
    def maximumSum(self, nums: List[int]) -> int:
        def get_square_free_part(n):
            if n == 0:
                return 0
            square_free = 1
            i = 2
            while i * i <= n:
                count = 0
                while n % i == 0:
                    count += 1
                    n = n // i
                if count % 2 == 1:
                    square_free *= i
                i += 1
            if n > 1:
                square_free *= n
            return square_free

        groups = defaultdict(int)
        for num in nums:
            s = get_square_free_part(num)
            groups[s] += num

        return max(groups.values())
