from functools import lru_cache

def count_set_bits_less(s, p):
    s = list(map(int, s))
    length = len(s)

    @lru_cache(maxsize=None)
    def dp(pos, count, tight):
        if pos == length:
            # Check if count == p
            return 1 if count == p else 0
        res = 0
        max_bit = s[pos] if tight else 1
        for bit in [0, 1]:
            if bit > max_bit:
                continue
            new_tight = tight and (bit == max_bit)
            new_count = count + (bit == 1)
            res += dp(pos+1, new_count, new_tight)
        return res

    # The function returns the count of numbers less than or equal to n with exactly p set bits.
    # But we need numbers less than n, so we need to subtract 1 if the number is equal to n.
    # However, the function as written includes numbers up to n. So to get numbers less than n, we need to subtract the count of numbers equal to n with exactly p set bits.
    # So first, compute the total count up to n (including n), then subtract the count for n if it has exactly p set bits.

    total = dp(0, 0, True)
    # Now, compute if n itself has exactly p set bits.
    n_set_bits = bin(int(s, 2)).count('1')
    if n_set_bits == p:
        # subtract 1, because n is not included.
        total -= 1
    return total
class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        m = len(s)

        # Precompute the powers of two up to m
        powers = []
        e = 0
        while True:
            current = 1 << e
            if current > m:
                break
            powers.append(current)
            e += 1

        # Handle cases based on k
        if k == 0:
            return 0
        elif k == 1:
            target_p = 1
            return self.count_p_set_bits(s, target_p) % MOD
        else:
            total = 0
            for p in powers:
                cnt = self.count_p_set_bits(s, p)
                total += cnt
            return total % MOD

    def count_p_set_bits(self, s: str, p: int) -> int:
        bits = list(map(int, s))
        n = len(bits)
        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dp(pos, tight, count, leading_zero):
            if pos == n:
                return 1 if count == p else 0
            limit = bits[pos] if tight else 1
            total = 0
            for digit in [0, 1]:
                if digit > limit:
                    continue
                new_tight = tight and (digit == limit)
                new_leading_zero = leading_zero and (digit == 0)
                new_count = count
                if not new_leading_zero:
                    if digit == 1:
                        new_count += 1
                total += dp(pos + 1, new_tight, new_count, new_leading_zero)
            return total

        return dp(0, True, 0, True)
class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        max_c = 800
        dp = [0] * (max_c + 1)
        for c in range(2, max_c + 1):
            cnt = bin(c).count('1')
            dp[c] = 1 + dp[cnt]

        def count_m_bits(s, m):
            n = len(s)
            from functools import lru_cache

            @lru_cache(maxsize=None)
            def dp_digit(pos, tight, bits, leading_zero):
                if pos == n:
                    if leading_zero:
                        return 0
                    return 1 if bits == m else 0
                res = 0
                max_digit = int(s[pos]) if tight else 1
                for digit in range(0, max_digit + 1):
                    new_tight = tight and (digit == max_digit)
                    new_leading_zero = leading_zero and (digit == 0)
                    new_bits = bits
                    if not new_leading_zero:
                        if digit == 1:
                            new_bits += 1
                    res += dp_digit(pos + 1, new_tight, new_bits, new_leading_zero)
                return res
            return dp_digit(0, True, 0, True)

        total = 0
        n_val = int(s, 2)
        if n_val > 1:
            total += 1

        for c in range(1, max_c + 1):
            count_c = count_m_bits(s, c)
            if c == 1:
                if k >= 1:
                    if n_val > 1:
                        total += (count_c - 1)
            else:
                if dp[c] <= k - 1:
                    total += count_c

        return total % MOD
class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        m = len(s)

        # Precompute f(c) for c from 1 to m
        memo_f = {}

        def compute_f(c):
            if c == 1:
                return 0
            if c in memo_f:
                return memo_f[c]
            bits = bin(c).count('1')
            res = 1 + compute_f(bits)
            memo_f[c] = res
            return res

        for c in range(1, m + 1):
            compute_f(c)

        total = 0

        def count_numbers_less_than_s(c):
            m_s = len(s)
            from functools import lru_cache

            @lru_cache(maxsize=None)
            def dp(pos, count, tight, leading_zero):
                if pos == m_s:
                    return 1 if (not leading_zero and count == c) else 0
                limit = int(s[pos]) if tight else 1
                total = 0
                for d in range(0, limit + 1):
                    new_tight = tight and (d == limit)
                    new_leading_zero = leading_zero and (d == 0)
                    if new_leading_zero:
                        new_count = 0
                    else:
                        if leading_zero and d == 1:
                            new_count = 1
                        else:
                            new_count = count + d
                    if new_count > c:
                        continue
                    total += dp(pos + 1, new_count, new_tight, new_leading_zero)
                    total %= MOD
                return total
            return dp(0, 0, True, True)

        for c in range(1, m + 1):
            if compute_f(c) <= k - 1:
                cnt = count_numbers_less_than_s(c)
                total = (total + cnt) % MOD

        return total
