    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7

        # Precompute steps_for_c for all c up to len(s)
        max_c = len(s)
        memo_steps = {}

        def compute_steps(c):
            if c == 1:
                return 0
            if c in memo_steps:
                return memo_steps[c]
