class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        max_c = len(s)
        memo_steps = {}

        def get_steps(c):
            if c == 1:
                return 0
            if c in memo_steps:
                return memo_steps[c]
            count_c = bin(c).count('1')
            res = 1 + get_steps(count_c)
            memo_steps[c] = res
            return res

        valid_cs = []
        for c in range(1, max_c + 1):
            steps_c = get_steps(c)
            if steps_c <= k - 1:
                valid_cs.append(c)

        def count_c_bits(s_str, c):
            bits = [int(ch) for ch in s_str]
            n = len(bits)
            from functools import lru_cache

            @lru_cache(maxsize=None)
            def dp(pos, tight, count):
                if pos == n:
                    return 1 if (not tight) and (count == c) else 0
                res = 0
                max_bit = bits[pos] if tight else 1
                for bit in [0, 1]:
                    if bit > max_bit:
                        continue
                    new_tight = tight and (bit == max_bit)
                    new_count = count + (bit == 1)
                    if new_count > c:
                        continue
                    res += dp(pos + 1, new_tight, new_count)
                return res

            return dp(0, True, 0)

        total = 0
        for c in valid_cs:
            cnt = count_c_bits(s, c)
            total = (total + cnt) % MOD

        return total % MOD

