            root_x = find(x)
            root_y = find(y)
            if root_x != root_y:
                parent[root_y] = root_x

        for i in range(n):
            for j in range(i + 1, n):
                set_i = set(properties[i])
                set_j = set(properties[j])
                if len(set_i & set_j) >= k:
                    union(i, j)

        roots = set()
        for x in range(n):
            roots.add(find(x))

        return len(roots)
