class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        sets = [set(arr) for arr in properties]
        adj = [[] for _ in range(n)]

        for i in range(n):
            for j in range(n):
                if i != j and len(sets[i] & sets[j]) >= k:
                    adj[i].append(j)

        visited = [False] * n
        count = 0

        for i in range(n):
            if not visited[i]:
                count += 1
                queue = deque([i])
                visited[i] = True
